const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd
b=pd.read_csv('production_batches.csv');q=pd.read_csv('quality_inspections.csv');p=pd.read_csv('products.csv');c=pd.read_csv('daily_factory_conditions.csv')
d=b.merge(q,on=['batch_id','product_id']).merge(p,on='product_id'); med=d.groupby('product_id').rejected_pct.median();d['resid']=d.rejected_pct-d.product_id.map(med);d['rej']=d.inspection_result.eq('REJECTED')
for rng in [(75,100),(350,360),(140,155)]:
 z=d[d.production_day.between(*rng)].groupby('production_day').agg(n=('batch_id','size'),mean=('resid','mean'),med=('resid','median'),rej=('rej','sum'),p90=('resid',lambda x:x.quantile(.9))).join(c.set_index('day'))
 print('\n',rng);print(z.to_string())
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:15000});
text(r.output);

